<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref } from 'vue'
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Cloud, Database, Download, Ellipsis, File, Files, Folder, FolderOpen, HardDrive, KeyRound, LayoutDashboard, ListChecks, LoaderCircle, LockKeyhole, LogOut, Menu, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldCheck, Shield, SlidersHorizontal, Square, Terminal, Trash2, UnlockKeyhole, X } from 'lucide-vue-next'
import { api, ApiError, bytes, date, dateInZone, isActive, setCSRF, statusLabel, tone } from './api'
import ResultReport from './ResultReport.vue'
import RcloneAuthorization from './RcloneAuthorization.vue'
import type { Entity, List } from './api'

const nav = [
  { id: 'overview', title: '总览', icon: LayoutDashboard, eyebrow: 'VAULT OVERVIEW', description: '掌握备份状态，让每一次恢复都有据可查。' },
  { id: 'accounts', title: '存储账号', icon: Cloud, eyebrow: 'CLOUD ACCOUNTS', description: '连接 OneDrive，验证访问并分配项目容量预算。' },
  { id: 'pools', title: '存储池', icon: Database, eyebrow: 'STORAGE POOLS', description: '将可用账号组合成池，为文件集合分配稳定归属。' },
  { id: 'sources', title: '备份源', icon: FolderOpen, eyebrow: 'BACKUP SOURCES', description: '选择服务器已挂载的目录，设置范围与读取策略。' },
  { id: 'plans', title: '备份计划', icon: Clock3, eyebrow: 'BACKUP PLANS', description: '安排增量备份，设置明确的时区与历史保留策略。' },
  { id: 'restore', title: '恢复中心', icon: ArrowDownToLine, eyebrow: 'RECOVERY CENTER', description: '从已发布的全局恢复点，找回完整目录或指定文件。' },
  { id: 'tasks', title: '任务中心', icon: ListChecks, eyebrow: 'ACTIVITY & TASKS', description: '查看真实执行阶段、传输统计和可追溯的任务日志。' },
  { id: 'security', title: '安全与维护', icon: ShieldCheck, eyebrow: 'SECURITY & MAINTENANCE', description: '保存恢复资料，检查仓库并执行受控维护。' },
]
const selectedNav = ref(location.hash.slice(1).split('?')[0] || 'overview')
const current = computed(() => nav.find(n => n.id === selectedNav.value) ?? nav[0]!)
const sidebarOpen = ref(false)
const status = ref<any>(null)
const busy = ref(false)
const loading = ref(false)
const booting = ref(true)
const error = ref<{ message: string; code: string; retryable: boolean } | null>(null)
const notice = ref('')
const connectionProblem = ref(false)
const data = reactive<Record<string, Entity[]>>({ accounts: [], pools: [], sources: [], plans: [], tasks: [], points: [], repos: [], audit: [] })
const catalog = reactive<Record<string,Entity[]>>({accounts:[],pools:[],sources:[],plans:[]})
const totals = reactive<Record<string, number>>({})
const offsets = reactive<Record<string, number>>({})
const pageSize = 30
const listEndpoints: Record<string, string> = {accounts:'/accounts',pools:'/pools',sources:'/sources',plans:'/plans',tasks:'/tasks',points:'/recovery-points',repos:'/repositories',audit:'/audit-events'}
const modal = ref('')
const form = reactive<Record<string, any>>({})
const authForm = reactive({ username: '', password: '', recovery_password: '', mode: 'create', recovery_kit: '' })
const setupAgreed = ref(false)
const importFilename = ref('')
const activeAccount = ref<Entity | null>(null)
const accountStep = ref(1)
const drives = ref<Entity[]>([])
const chosenDrive = ref('')
const accountBudget = reactive({ budget: 800, reserve: 50, maintenance: 50 })
const browseState = reactive({ path: '', items: [] as any[], total: 0, offset: 0 })
const selectedPoint = ref<Entity | null>(null)
const filesState = reactive({ items: [] as Entity[], total: 0, offset: 0, prefix: '', search: '', source: '' })
const selectedFiles = ref<{ source_id: string; path: string }[]>([])
const restoreForm = reactive({ target: '', overwrite: false, allow_partial: false, source_ids: [] as string[] })
const restorePreview = ref<any>(null)
const activeTask = ref<Entity | null>(null)
const logs = reactive({ items: [] as any[], total: 0, offset: 0 })
const detail = ref<any>(null)
const retentionPreview = ref<any>(null)
const retentionSelection = ref<string[]>([])
const repositorySelection = ref<string[]>([])
const maintenanceForm = reactive({ mode: 'structure', sample: '10%', plan_id: '', repository_id: '', target_account_id: '', old_location_index: '' as string | number })
const oldRepositoryLocations = computed(() => {
  const repository = data.repos!.find(r=>r.id===maintenanceForm.repository_id)
  return (repository?.locations??[]).map((location:any,index:number)=>({...location,index})).filter((location:any)=>location.path&&location.status!=='deleted'&&!(location.account_id===repository?.account_id&&location.path===repository?.path))
})
const confirmAction = ref<null | (() => Promise<void>)>(null)
const confirmText = ref('')
const confirmTitle = ref('')
const taskFilter = ref('all')
const accountSearch = ref('')
let poll: ReturnType<typeof setInterval> | undefined
let noticeTimer: ReturnType<typeof setTimeout> | undefined
const authenticated = computed(() => status.value?.authenticated)
const recoveryMode = computed(() => status.value?.mode === 'recovery')
const engineMissing = computed(() => {
  const engines = status.value?.engines
  if (!engines) return []
  return Object.entries(engines).filter(([,v]: [string, any]) => v === false || v?.available === false).map(([k]) => k)
})
const filteredAccounts = computed(() => data.accounts!.filter(a => `${a.name} ${a.drive_name} ${a.drive_id}`.toLowerCase().includes(accountSearch.value.toLowerCase())))
const filteredTasks = computed(() => data.tasks!.filter(t => taskFilter.value === 'all' || (taskFilter.value === 'running' ? isActive(t.status) : taskFilter.value === 'failed' ? ['failed','partial_failed','interrupted'].includes(t.status) : ['completed','success','complete'].includes(t.status))))
const totalBudget = computed(() => catalog.accounts!.filter(a => a.enabled && a.verified).reduce((n,a) => n + Number(a.budget_bytes || 0),0))
const projectUsed = computed(() => catalog.accounts!.filter(a => a.enabled && a.verified).reduce((n,a) => n + Number(a.project_used_bytes || 0),0))
const latestSuccess = computed(() => data.tasks!.find(t => ['completed','complete','success'].includes(t.status) && (t.kind === 'backup' || t.kind === 'run')))
const activeTasks = computed(() => data.tasks!.filter(t => isActive(t.status)))
const unprotectedSources = computed(() => catalog.sources!.filter(s => !catalog.plans!.some(p => p.enabled && p.source_ids?.includes(s.id))))
const accountName = (id: string) => catalog.accounts!.find(a => a.id === id)?.name ?? id
const sourceName = (id: string) => catalog.sources!.find(a => a.id === id)?.name ?? id
const poolName = (id: string) => catalog.pools!.find(a => a.id === id)?.name ?? id
const planName = (id: string) => catalog.plans!.find(a => a.id === id)?.name ?? id
const taskKind = (kind: string) => { const labels:Record<string,string> = {backup:'备份',run:'备份',preview:'分配预览',restore:'恢复',check:'完整性检查',retention:'历史清理',migrate:'仓库迁移',migration:'仓库迁移',discover:'云端发现'}; return labels[kind] ?? kind }
const usage = (a: Entity) => a.budget_bytes ? Math.min(100, Number(a.project_used_bytes || 0) / Number(a.budget_bytes) * 100) : 0
const auditLabel=(value:string)=>{const labels:Record<string,string>={'account.create':'添加账号','account.update':'修改账号','account.delete':'删除账号','account.authorize':'账号授权','account.authorized':'账号授权完成','account.rclone_authorized':'Rclone 标准授权完成','account.rclone_imported':'导入 Rclone 授权','account.verify':'验证账号','account.verified':'账号验证完成','account.quota':'查询配额','pool.save':'保存存储池','source.save':'保存备份源','storage_pools.delete':'删除存储池','sources.delete':'删除备份源','recovery-kit.export':'导出恢复包','repository.check':'仓库检查','repository.migrate':'仓库迁移','repository.cleanup_old':'清理旧仓库副本','retention.complete':'历史清理完成','restore.complete':'恢复完成','catalog.discover':'发现云端目录','plan.save':'保存备份计划','plan.delete':'删除备份计划','recovery_point.protect':'修改恢复点保护','backup.commit':'发布完整恢复点'};return labels[value]??value}
function showError(e: unknown) { error.value = { message: e instanceof Error ? e.message : '操作未完成', code: e instanceof ApiError ? e.code : 'client_error', retryable: e instanceof ApiError && e.retryable }; if (e instanceof ApiError && e.status === 401) void refreshStatus() }
function toast(message: string) { notice.value = message; if (noticeTimer) clearTimeout(noticeTimer); noticeTimer = setTimeout(() => notice.value = '', 6500) }
async function action(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = null; try { await fn() } catch(e) { showError(e) } finally { busy.value = false } }
async function refreshStatus() { status.value = await api('/status'); setCSRF(status.value.csrf_token ?? '');connectionProblem.value=false }
async function loadList(key: string) { const response = await api<List>(`${listEndpoints[key]}?limit=${pageSize}&offset=${offsets[key] ?? 0}`); data[key] = response.items ?? []; totals[key] = response.total ?? data[key]!.length;if(key in catalog){if((offsets[key]??0)===0&&totals[key]<=pageSize)catalog[key]=data[key]!;else{const entries:Entity[]=[];let offset=0;while(offset<totals[key]!){const page=await api<List>(`${listEndpoints[key]}?limit=500&offset=${offset}`);entries.push(...(page.items??[]));if(!page.items?.length)break;offset+=page.items.length}catalog[key]=entries}} }
async function refresh(silent = false) {
  if (!authenticated.value || loading.value) return
  loading.value = true
  const keys = selectedNav.value === 'overview' ? ['accounts','sources','plans','tasks','points'] : selectedNav.value === 'restore' ? ['points','sources'] : selectedNav.value === 'security' ? ['repos','accounts','plans','audit'] : [selectedNav.value]
  try {
    const outcomes = await Promise.allSettled(keys.filter(k => listEndpoints[k]).map(loadList))
    for (const item of outcomes) if (item.status === 'rejected' && !silent) showError(item.reason)
  } finally { loading.value = false }
}
async function initialLoad() { await refreshStatus(); if (authenticated.value) { const results = await Promise.allSettled(['accounts','pools','sources','plans','tasks','points','repos',...(selectedNav.value==='security'?['audit']:[])].map(loadList)); for (const r of results) if (r.status === 'rejected') showError(r.reason) } }
function navigate(id: string) { selectedNav.value = id; location.hash = id; sidebarOpen.value = false; error.value = null; void refresh();void nextTick(()=>window.scrollTo(0,0)) }
function onHash() { const id = location.hash.slice(1).split('?')[0]; if (nav.some(n => n.id === id)) { selectedNav.value = id; void refresh();void nextTick(()=>window.scrollTo(0,0)) } }
function closeModal() { if (busy.value) return; modal.value = ''; confirmAction.value = null }
function openForm(type: string, entity?: Entity) {
  error.value = null
  for (const key in form) delete form[key]
  if (type === 'pool') Object.assign(form, { name:'', account_ids:[], catalog_replicas:2, shard_target_gib:150 })
  if (type === 'source') Object.assign(form, { name:'',path:'',excludes_text:'',include_hidden:true,max_file_mib:0,one_file_system:true })
  if (type === 'plan') Object.assign(form, {name:'',source_ids:[],pool_id:'',schedule:'0 2 * * *',timezone:'Asia/Shanghai',enabled:true,excludes_text:'',daily:7,weekly:4,monthly:12,retry_count:2,bandwidth_kib:0})
  if (entity) Object.assign(form, entity, {excludes_text: (entity.excludes ?? []).join('\n'),shard_target_gib:Number(entity.shard_target_bytes ?? 0)/1024**3,max_file_mib:Number(entity.max_file_bytes ?? 0)/1024**2,...entity.retention})
  modal.value = type
}
async function submitAuth() { await action(async () => {
  const wasSetup = !status.value.initialized
  if(wasSetup && authForm.password===authForm.recovery_password)throw new Error('登录密码与备份库保护密码需要分别设置，不能相同。')
  if (!status.value.initialized && !setupAgreed.value) throw new Error('请确认已了解恢复资料保存要求。')
  let kit: any = undefined
  if (authForm.mode === 'recovery') { try { kit = JSON.parse(authForm.recovery_kit) } catch { throw new Error('恢复包不是有效的 JSON 文件。') } }
  const result = await api(status.value.initialized ? '/auth/login' : '/setup', { method:'POST', body: status.value.initialized ? {username:authForm.username,password:authForm.password} : {...authForm,recovery_kit:kit} })
  setCSRF(result.csrf_token ?? ''); authForm.password = ''; authForm.recovery_password = ''; authForm.recovery_kit = ''
  await initialLoad()
  await nextTick();window.scrollTo(0,0)
  if (wasSetup) { toast(authForm.mode==='create'?'备份库已创建，请导出并离线保存恢复包。':'恢复节点已建立，请重新授权账号并发现已有备份。'); navigate('security') }
}) }
async function readKit(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (file) { if (file.size > 10*1024*1024) { showError(new Error('恢复包超过 10 MiB，请检查文件。')); return }; authForm.recovery_kit = await file.text(); importFilename.value = file.name } }
async function logout() { await action(async () => { await api('/auth/logout',{method:'POST',body:{}}); await refreshStatus(); for (const key in data) data[key] = [];for(const key in catalog)catalog[key]=[] }) }
async function saveForm() { await action(async () => {
  const kind = modal.value
  const endpoint = kind === 'pool' ? '/pools' : kind === 'source' ? '/sources' : '/plans'
  const payload = {...form}
  if (kind === 'pool') payload.shard_target_bytes = Math.round(Number(form.shard_target_gib)*1024**3)
  if (kind === 'source') payload.max_file_bytes = Math.round(Number(form.max_file_mib)*1024**2)
  if (kind === 'source' || kind === 'plan') payload.excludes = String(form.excludes_text || '').split('\n').map(v=>v.trim()).filter(Boolean)
  if (kind === 'plan') payload.retention = {daily:Number(form.daily),weekly:Number(form.weekly),monthly:Number(form.monthly)}
  await api(form.id ? `${endpoint}/${form.id}` : endpoint,{method:form.id?'PUT':'POST',body:payload}); modal.value = ''; await loadList(kind === 'pool'?'pools':kind==='source'?'sources':'plans'); toast('配置已保存。')
}) }
async function toggleEntity(key: string, entity: Entity) { await action(async () => { await api(`${listEndpoints[key]}/${entity.id}`,{method:'PUT',body:{...entity,enabled:!entity.enabled}}); await loadList(key); toast(entity.enabled?'已暂停新的分配或执行。':'已启用。') }) }
function askConfirm(title: string, text: string, fn: () => Promise<void>) { confirmTitle.value = title; confirmText.value = text; confirmAction.value = fn; modal.value='confirm'; error.value=null }
function removeEntity(key: string, entity: Entity) { askConfirm('删除配置',`确认删除「${entity.name}」？服务会检查已有恢复点与计划的依赖。删除配置不会代替受控的云端数据清理。`,async () => { await api(`${listEndpoints[key]}/${entity.id}`,{method:'DELETE',body:{version:entity.version}}); modal.value=''; await loadList(key); toast('配置已删除。') }) }
function openAccount(existing?: Entity) { activeAccount.value = existing ?? null; accountStep.value = existing ? 2 : 1; drives.value=[]; chosenDrive.value=''; form.name=existing?.name??''; form.backend=existing?.backend??'onedrive'; form.local_path=existing?.local_path??''; accountBudget.budget=Number(existing?.budget_bytes??800*1024**3)/1024**3; accountBudget.reserve=Number(existing?.cloud_reserve_bytes??50*1024**3)/1024**3; accountBudget.maintenance=Number(existing?.maintenance_reserve_bytes??50*1024**3)/1024**3; modal.value='account'; error.value=null; if(existing?.backend==='local') accountStep.value=3;else if(['authorized','awaiting_drive_selection'].includes(existing?.status)||existing?.verified)void loadDrives() }
function handleOAuthReturn() {const params=new URLSearchParams(location.hash.split('?')[1]??'');if(params.get('oauth_error'))showError(new ApiError('微软授权未完成，请重新授权。',params.get('oauth_error')!,true,400));const id=params.get('authorized');if(id){const account=data.accounts!.find(a=>a.id===id);if(account)openAccount(account);else showError(new Error('授权返回的账号不在当前列表，请刷新并继续设置。'));history.replaceState(null,'','#accounts')}}
async function createAccount() { await action(async()=> { activeAccount.value = await api('/accounts',{method:'POST',body:{name:form.name,backend:form.backend,local_path:form.local_path,budget_bytes:Math.round(accountBudget.budget*1024**3),cloud_reserve_bytes:Math.round(accountBudget.reserve*1024**3),maintenance_reserve_bytes:Math.round(accountBudget.maintenance*1024**3)}}); accountStep.value=2; await loadList('accounts'); if(form.backend==='local') accountStep.value=3 }) }
async function authorizeAccount() { await action(async()=> { const response=await api(`/accounts/${activeAccount.value!.id}/authorize`,{method:'POST',body:{}}); location.assign(response.authorization_url) }) }
async function onRcloneAuthorized(account: Entity) { activeAccount.value=account; await loadDrives(); await action(()=>loadList('accounts')) }
async function loadDrives() { await action(async()=> { const response=await api<List>(`/accounts/${activeAccount.value!.id}/drives`); drives.value=response.items??[]; accountStep.value=3 }) }
async function verifyAccount() { await action(async()=> { activeAccount.value=await api(`/accounts/${activeAccount.value!.id}/verify`,{method:'POST',body:{drive_id:chosenDrive.value,version:activeAccount.value!.version,budget_bytes:Math.round(accountBudget.budget*1024**3),cloud_reserve_bytes:Math.round(accountBudget.reserve*1024**3),maintenance_reserve_bytes:Math.round(accountBudget.maintenance*1024**3)}}); accountStep.value=4; await loadList('accounts'); toast('访问验证已完成，可以将此账号加入存储池。') }) }
async function refreshAccountQuota(account:Entity){await action(async()=>{await api(`/accounts/${account.id}/quota`,{method:'POST',body:{}});await loadList('accounts');toast('已重新查询云端配额与项目占用。')})}
function editAccountSettings(account:Entity){for(const key in form)delete form[key];Object.assign(form,account,{budget_gib:Number(account.budget_bytes)/1024**3,reserve_gib:Number(account.cloud_reserve_bytes)/1024**3,maintenance_gib:Number(account.maintenance_reserve_bytes)/1024**3});modal.value='account-settings';error.value=null}
async function saveAccountSettings(){await action(async()=>{await api(`/accounts/${form.id}`,{method:'PUT',body:{name:form.name,version:form.version,enabled:form.enabled,budget_bytes:Math.round(form.budget_gib*1024**3),cloud_reserve_bytes:Math.round(form.reserve_gib*1024**3),maintenance_reserve_bytes:Math.round(form.maintenance_gib*1024**3)}});modal.value='';await loadList('accounts');toast('账号名称与容量预算已保存。')})}
async function browse(path='', offset=0) { await action(async()=> { const response=await api(`/browse?path=${encodeURIComponent(path)}&limit=${pageSize}&offset=${offset}`); browseState.path=response.path??path; browseState.items=response.items??[]; browseState.total=response.total??browseState.items.length; browseState.offset=offset }) }
function openBrowser() { modal.value='browse'; browseState.path=''; browseState.offset=0; void browse() }
function choosePath(path: string) { form.path=path; if(!form.name) form.name=path.split('/').filter(Boolean).pop()??'备份源'; modal.value='source' }
async function startPlan(plan: Entity, mode: 'run'|'preview') { await action(async()=> { const task=await api(`/plans/${plan.id}/${mode}`,{method:'POST',body:{},task:true}); toast(mode==='preview'?'正在扫描并生成真实分配预览。':'备份任务已提交。'); await loadList('tasks'); await openTask(task) }) }
async function openTask(task: Entity) { activeTask.value=task; logs.offset=0; modal.value='task'; detail.value=null; await Promise.all([readTask(),loadLogs()]) }
async function readTask() { if (!activeTask.value) return; try { activeTask.value=await api(`/tasks/${activeTask.value.id}`); detail.value=activeTask.value?.result??null } catch(e) { showError(e) } }
async function loadLogs(offset=0) { if(!activeTask.value)return; try { const r=await api(`/tasks/${activeTask.value.id}/logs?limit=100&offset=${offset}`); logs.items=r.items??[]; logs.total=r.total??logs.items.length; logs.offset=offset } catch(e) {showError(e)} }
function cancelTask(task: Entity) { askConfirm('取消任务',`取消「${taskKind(task.kind)}」会终止相关引擎进程。已经写入的残留数据需要重新对账，服务不会将任务标记为完成。`,async()=>{await api(`/tasks/${task.id}/cancel`,{method:'POST',body:{},task:true});modal.value='';await loadList('tasks');toast('取消请求已提交。')}) }
async function selectPoint(point: Entity) { selectedPoint.value=point; selectedFiles.value=[]; restorePreview.value=null; filesState.offset=0;filesState.search='';filesState.prefix='';filesState.source='';restoreForm.source_ids=[];restoreForm.target=status.value.restore_roots?.[0]??'';try{await loadFiles()}catch(e){showError(e)} }
async function loadFiles(offset=0) { if(!selectedPoint.value)return; const q=new URLSearchParams({limit:String(pageSize),offset:String(offset),prefix:filesState.prefix,search:filesState.search,source_id:filesState.source});const r=await api(`/recovery-points/${selectedPoint.value.id}/files?${q}`);filesState.items=r.items??[];filesState.total=r.total??filesState.items.length;filesState.offset=offset }
function hasFile(f: Entity) { return selectedFiles.value.some(s=>s.path===f.path&&s.source_id===f.source_id) }
function toggleFile(f: Entity) { restoreForm.source_ids=[];selectedFiles.value=hasFile(f)?selectedFiles.value.filter(s=>!(s.path===f.path&&s.source_id===f.source_id)):[...selectedFiles.value,{source_id:f.source_id,path:f.path}];restorePreview.value=null }
function restoreBody() { return {point_id:selectedPoint.value?.id,source_ids:restoreForm.source_ids,paths:selectedFiles.value,target:restoreForm.target,overwrite:restoreForm.overwrite,allow_partial:restoreForm.allow_partial} }
async function previewRestore() { await action(async()=> { restorePreview.value=await api('/restore/preview',{method:'POST',body:restoreBody()});modal.value='restore-preview' }) }
function executeRestore() { const fn=async()=> { const task=await api('/restore',{method:'POST',body:restoreBody(),task:true});modal.value='';await loadList('tasks');await openTask(task);toast('恢复任务已提交，请在任务报告中确认结果。') }; if(restoreForm.overwrite)askConfirm('确认覆盖恢复',`目标 ${restoreForm.target} 中的冲突文件会按预检查的覆盖策略处理。请确认已查看冲突列表并保存必要的现有内容。`,fn);else void action(fn) }
async function protectPoint(point: Entity) { await action(async()=> {await api(`/recovery-points/${point.id}/protect`,{method:'POST',body:{protected:!point.protected,version:point.version}});await loadList('points');if(selectedPoint.value?.id===point.id)selectedPoint.value=data.points!.find(p=>p.id===point.id)??null;toast(point.protected?'已取消手动保护。':'恢复点已受到手动保护。')}) }
async function unlock() { await action(async()=> {await api('/security/unlock',{method:'POST',body:{password:form.password}});form.password='';modal.value='';await refreshStatus();toast('备份库已解锁。')}) }
async function lock() { await action(async()=>{await api('/security/lock',{method:'POST',body:{}});await refreshStatus();toast('备份库已锁定。')}) }
async function exportKit() { await action(async()=> { const kit=await api('/security/recovery-kit',{method:'POST',body:{password:form.password}});const blob=new Blob([JSON.stringify(kit,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`vaultpilot-recovery-${status.value.vault_id}.json`;a.click();URL.revokeObjectURL(url);form.password='';modal.value='';toast('已下载加密恢复包。请在另一处离线保存，并保管好保护密码。') }) }
async function maintenance(endpoint: string, payload: any) { await action(async()=> { const task=await api(endpoint,{method:'POST',body:payload,task:true});await loadList('tasks');await openTask(task) }) }
async function previewRetention() { await action(async()=> {retentionPreview.value=await api('/maintenance/retention/preview',{method:'POST',body:{plan_id:maintenanceForm.plan_id}});retentionSelection.value=[...(retentionPreview.value.delete_ids??[])];modal.value='retention-preview'}) }
function applyRetention() { const ids=[...retentionSelection.value];askConfirm('确认清理历史',`本次将删除已选择的 ${ids.length} 个全局恢复点，并清理不再被有效恢复点引用的数据。此操作无法撤销。`,async()=>{const task=await api('/maintenance/retention',{method:'POST',body:{plan_id:maintenanceForm.plan_id,point_ids:ids,confirm:true},task:true});await openTask(task)}) }
function migrate() { askConfirm('确认整仓迁移','将复制完整仓库、校验并提交新位置映射。旧位置保留用于观察；迁移期间该仓库禁止并发写入。',async()=>{const task=await api('/maintenance/migrate',{method:'POST',body:{repository_id:maintenanceForm.repository_id,target_account_id:maintenanceForm.target_account_id,confirm:true},task:true});await openTask(task)}) }
function cleanupOldLocation() {
  const repositoryID=maintenanceForm.repository_id
  const index=Number(maintenanceForm.old_location_index)
  const location=oldRepositoryLocations.value.find((l:any)=>l.index===index)
  if(maintenanceForm.old_location_index===''||!location||recoveryMode.value)return
  askConfirm('确认删除旧仓库副本',`将删除「${accountName(location.account_id)}」中的旧副本 ${location.path}。这是不可撤销的云端数据删除。服务会先对当前有效位置执行完整读取校验，通过后才删除选定的旧位置；请确认观察期和恢复演练已经完成。`,async()=>{const task=await api('/maintenance/migrate',{method:'POST',body:{repository_id:repositoryID,cleanup_old:true,old_location_index:index,old_location_path:location.path,confirm:true},task:true});maintenanceForm.old_location_index='';await openTask(task)})
}
async function changePage(key: string, direction: number) { offsets[key]=Math.max(0,(offsets[key]??0)+direction*pageSize);await action(()=>loadList(key)) }
onMounted(async()=>{window.addEventListener('hashchange',onHash);try{await initialLoad();if(authenticated.value)handleOAuthReturn()}catch(e){showError(e)}finally{booting.value=false}poll=setInterval(async()=>{if(!authenticated.value||busy.value)return;try{await refreshStatus();await refresh(true);if(modal.value==='task'&&activeTask.value){await readTask();await loadLogs(logs.offset)}}catch(e){connectionProblem.value=true;if(e instanceof ApiError&&e.status===401)void refreshStatus()}},5000)})
onUnmounted(()=>{if(poll)clearInterval(poll);if(noticeTimer)clearTimeout(noticeTimer);window.removeEventListener('hashchange',onHash)})
</script>

<template>
  <div v-if="booting" class="boot-screen"><div class="brand-symbol"><ShieldCheck :size="26" /></div><LoaderCircle class="spin" :size="22" /><span>正在连接 VaultPilot…</span></div>
  <div v-else-if="!status || !status.initialized || !authenticated" class="auth-layout">
    <aside class="auth-brand">
      <a class="brand"><span class="brand-symbol"><ShieldCheck :size="24" /></span><span>VaultPilot<small>加密备份管理</small></span></a>
      <div class="auth-intro"><span class="eyebrow light">YOUR DATA. YOUR CONTROL.</span><h1>数据有归处，<br>恢复有把握。</h1><p>将服务器目录加密备份到多个 OneDrive，<br>保留历史，在需要时找回它们。</p></div>
      <div class="vault-illustration" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="vault-core"><ShieldCheck :size="64" :stroke-width="1.3" /></div><span class="orbit-node node-a"><Cloud :size="26" /></span><span class="orbit-node node-b"><Folder :size="24" /></span><span class="orbit-node node-c"><KeyRound :size="22" /></span><div class="graphic-caption">本地加密 · 稳定分配 · 历史恢复</div></div>
      <p class="auth-footer">多账号容量分配不等于业务数据多副本。<br>请为重要数据保留独立的第二份备份。</p>
    </aside>
    <main class="auth-content">
      <div class="auth-form">
        <span class="eyebrow">{{ status?.initialized ? 'WELCOME BACK' : 'LET’S GET STARTED' }}</span><h2>{{status?.initialized?'欢迎回来':'建立你的备份空间'}}</h2><p class="text-secondary">{{status?.initialized?'登录管理后台，继续守护你的数据。':'先创建一个备份库，或连接已有备份库进行恢复。'}}</p>
        <div v-if="error" class="alert danger"><Shield :size="18"/><div>{{error.message}}<small>{{error.code}}</small></div><button class="icon-button" @click="error=null"><X :size="16"/></button></div>
        <div v-if="!status" class="empty compact"><p>服务状态暂时无法读取。</p><button class="button primary" @click="action(initialLoad)"><RefreshCw :size="16"/>重新连接</button></div>
        <form v-else @submit.prevent="submitAuth">
          <div v-if="!status.initialized" class="setup-options"><button type="button" :class="{selected:authForm.mode==='create'}" @click="authForm.mode='create'"><Plus :size="19"/><strong>新建备份库</strong><small>开始新的加密备份</small></button><button type="button" :class="{selected:authForm.mode==='recovery'}" @click="authForm.mode='recovery'"><ArrowDownToLine :size="19"/><strong>连接已有备份库</strong><small>导入资料并恢复</small></button></div>
          <label class="field">管理员用户名<input v-model="authForm.username" required autocomplete="username" placeholder="输入用户名" /></label>
          <label class="field">{{status.initialized?'登录密码':'设置登录密码'}}<input v-model="authForm.password" type="password" required :minlength="status.initialized?1:12" autocomplete="current-password" placeholder="输入密码" /><small v-if="!status.initialized">至少 12 位，与备份库保护密码分开设置。</small></label>
          <template v-if="!status.initialized">
            <label v-if="authForm.mode==='recovery'" class="field">加密恢复包<label class="upload-area"><Download :size="21" /><span>{{importFilename||'选择离线保存的 .json 恢复包'}}</span><input type="file" accept=".json,application/json" @change="readKit" /></label></label>
            <label class="field">{{authForm.mode==='create'?'备份库保护密码':'恢复包保护密码'}}<input v-model="authForm.recovery_password" type="password" required minlength="12" autocomplete="new-password" placeholder="至少 12 位，请妥善保存" /><small>{{authForm.mode==='create'?'用于保护库密钥；遗失后无法解密备份。':'使用导出该恢复包时设置的保护密码。'}}</small></label>
            <label class="check-label agreement"><input v-model="setupAgreed" type="checkbox" required /><span>我了解需要离线保存恢复包与保护密码。原服务器丢失时，这些资料是恢复备份的必要条件。</span></label>
            <div class="small-note"><KeyRound :size="16" /><span>OneDrive 支持 Rclone 标准授权与配置导入，无需开通 Azure。连接后需验证 Drive 访问。</span></div>
          </template>
          <button class="button primary full" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="17"/>{{status.initialized?'登录后台':authForm.mode==='create'?'创建备份库':'导入并建立恢复节点'}}<ArrowRight v-if="!busy" :size="17"/></button>
        </form>
        <p class="auth-bottom"><LockKeyhole :size="14"/>云端内容与恢复清单加密保存</p>
      </div>
    </main>
  </div>

  <div v-else class="app-shell">
    <div v-if="sidebarOpen" class="sidebar-overlay" @click="sidebarOpen=false"></div>
    <aside class="sidebar" :class="{open:sidebarOpen}">
      <a class="brand" href="#overview" @click="navigate('overview')"><span class="brand-symbol"><ShieldCheck :size="24"/></span><span>VaultPilot<small>加密备份管理</small></span></a>
      <div class="vault-switch"><span class="vault-avatar"><Database :size="18"/></span><div><strong>{{recoveryMode?'恢复节点':'我的备份库'}}</strong><small>{{status.vault_id?.slice(0,12)||'独立加密空间'}}</small></div><LockKeyhole v-if="!status.unlocked" :size="15"/><ShieldCheck v-else :size="16"/></div>
      <span class="nav-caption">工作空间</span>
      <nav><a v-for="item in nav" :key="item.id" :href="`#${item.id}`" :class="{active:selectedNav===item.id}" @click.prevent="navigate(item.id)"><component :is="item.icon" :size="19" :stroke-width="1.7"/><span>{{item.title}}</span><span v-if="item.id==='tasks'&&activeTasks.length" class="nav-count">{{activeTasks.length}}</span></a></nav>
      <div class="sidebar-bottom"><div class="sidebar-tip"><ShieldCheck :size="19"/><div><strong>恢复资料，离线保存</strong><p>导出恢复包，为异机恢复<br>保留独立的解锁入口。</p><button @click="navigate('security')">前往安全设置 <ArrowUpRight :size="14"/></button></div></div><button class="sidebar-user" @click="logout" :disabled="busy"><span class="user-avatar">管</span><div><strong>管理员</strong><small>本机管理会话</small></div><LogOut :size="16"/></button></div>
    </aside>
    <div class="workspace">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" @click="sidebarOpen=true"><Menu :size="21"/></button><span>工作空间</span><ChevronRight :size="13"/><strong>{{current.title}}</strong></div><div class="topbar-actions"><span class="system-status"><i :class="{warn:!status.unlocked||engineMissing.length}"/>{{status.unlocked?'备份库已解锁':'备份库已锁定'}}</span><button class="icon-button" title="刷新当前数据" @click="action(()=>refresh())"><RefreshCw :size="17" :class="{spin:loading}"/></button><span class="topbar-avatar">管</span></div></header>
      <main class="main-content">
        <div class="page-heading"><div><span class="eyebrow">{{current.eyebrow}}</span><h1>{{current.title}}</h1><p>{{current.description}}</p></div><div class="heading-actions"><template v-if="['accounts','pools','sources','plans'].includes(selectedNav)"><button v-if="selectedNav==='accounts'" class="button primary" :disabled="!status.unlocked||busy" @click="openAccount()"><Plus :size="17"/>添加账号</button><button v-else class="button primary" :disabled="!status.unlocked||busy||recoveryMode&&selectedNav==='plans'" @click="openForm(selectedNav==='pools'?'pool':selectedNav==='sources'?'source':'plan')"><Plus :size="17"/>{{selectedNav==='pools'?'新建存储池':selectedNav==='sources'?'添加备份源':'新建计划'}}</button></template><button v-if="selectedNav==='overview'" class="button secondary" @click="navigate('plans')"><Clock3 :size="16"/>管理备份计划</button></div></div>
        <div v-if="connectionProblem" class="alert warning"><RefreshCw :size="18"/><div><strong>与服务的连接暂时中断</strong><p>以下数据为最后获取的状态，正在尝试重新连接。后台任务不依赖浏览器连接。</p></div></div><div v-if="error" class="alert danger global-error"><Shield :size="19"/><div><strong>{{error.message}}</strong><small>错误码：{{error.code}}{{error.retryable?' · 可以重试':''}}</small></div><button class="icon-button" @click="error=null"><X :size="17"/></button></div>
        <div v-if="!status.unlocked" class="alert warning"><LockKeyhole :size="19"/><div><strong>备份库当前处于锁定状态</strong><p>解锁后才能读取受保护的配置与执行备份、恢复和维护。</p></div><button class="button small secondary" @click="form.password='';modal='unlock'">解锁备份库</button></div>
        <div v-if="engineMissing.length" class="alert warning"><Terminal :size="19"/><div><strong>执行引擎不可用：{{engineMissing.join('、')}}</strong><p>请检查部署中引擎的安装与执行路径。管理界面可用，备份与恢复仍需要真实引擎。</p></div></div>
        <div v-if="recoveryMode" class="alert info"><ShieldCheck :size="19"/><div><strong>当前为恢复节点</strong><p>可重新授权、发现云端目录与恢复历史数据。备份、迁移及历史清理保持禁用。</p></div></div>

        <template v-if="selectedNav==='overview'">
          <div class="overview-banner"><div class="banner-icon"><ShieldCheck :size="33" :stroke-width="1.5"/></div><div><span class="eyebrow">{{latestSuccess?'YOUR BACKUP ACTIVITY':'READY FOR YOUR FIRST BACKUP'}}</span><h2>{{latestSuccess?'每一个恢复点，都是一份安心。':'从第一个备份计划开始。'}}</h2><p>{{latestSuccess?`最近一次备份完成于 ${date(latestSuccess.finished_at)}`:'添加存储账号与服务器目录，然后创建计划并预览分配。'}}</p></div><button class="button secondary" @click="navigate(latestSuccess?'restore':'accounts')">{{latestSuccess?'浏览恢复点':'连接 OneDrive'}}<ArrowRight :size="16"/></button><div class="banner-decoration" aria-hidden="true"><ShieldCheck :size="160" :stroke-width="0.8"/></div></div>
          <div class="stats-grid"><div class="stat-card"><div class="stat-title">项目存储占用<HardDrive :size="18"/></div><strong>{{bytes(projectUsed)}}</strong><div class="thin-meter"><span :style="{width:totalBudget?Math.min(100,projectUsed/totalBudget*100)+'%':'0%'}"/></div><p>已验证账号预算 {{bytes(totalBudget)}}</p></div><div class="stat-card"><div class="stat-title">存储账号<Cloud :size="18"/></div><strong>{{totals.accounts??0}}<small> 个</small></strong><p><span class="green-dot"/>{{catalog.accounts.filter(a=>a.enabled&&a.verified).length}} 个已验证并启用</p></div><div class="stat-card"><div class="stat-title">备份计划<Clock3 :size="18"/></div><strong>{{totals.plans??0}}<small> 个</small></strong><p>{{catalog.plans.filter(p=>p.enabled).length}} 个已启用 · {{activeTasks.length}} 个任务执行中</p></div><div class="stat-card"><div class="stat-title">全局恢复点<Files :size="18"/></div><strong>{{totals.points??0}}<small> 个</small></strong><p>包含历史目录与完整快照引用</p></div></div>
          <div class="overview-grid"><section class="panel"><div class="panel-head"><h2>最近任务<span class="label-sub">Recent activity</span></h2><button class="text-button" @click="navigate('tasks')">查看全部<ArrowRight :size="14"/></button></div><div v-if="!data.tasks.length" class="empty"><div class="empty-icon"><Activity :size="26"/></div><h3>还没有任务记录</h3><p>手动执行或定时触发备份后，会在这里显示真实进度。</p><button class="button secondary small" @click="navigate('plans')">设置备份计划</button></div><div v-else class="activity-list"><button v-for="task in data.tasks.slice(0,5)" :key="task.id" class="activity-row" @click="openTask(task)"><span class="activity-icon" :class="tone(task.status)"><Check v-if="tone(task.status)==='success'" :size="18"/><Activity v-else :size="18"/></span><div><strong>{{task.name||planName(task.plan_id)||taskKind(task.kind)}}</strong><p>{{taskKind(task.kind)}} · {{date(task.started_at)}}</p></div><span class="badge" :class="tone(task.status)">{{statusLabel(task.status)}}</span><ChevronRight :size="16"/></button></div></section><section class="panel health-panel"><div class="panel-head"><h2>需要关注</h2><span class="tiny-label">配置检查</span></div><div class="health-item"><span class="health-dot" :class="unprotectedSources.length?'warning':'success'"/><div><strong>{{unprotectedSources.length?'有目录尚未关联启用计划':'目录与计划'}}</strong><p>{{unprotectedSources.length?unprotectedSources.map(s=>s.name).join('、'):data.sources.length?'已登记目录均有关联的启用计划。':'添加服务器目录，建立可追溯的备份源。'}}</p></div><button class="icon-button" @click="navigate('sources')"><ArrowUpRight :size="17"/></button></div><div class="health-item"><span class="health-dot" :class="status.unlocked?'success':'warning'"/><div><strong>密钥状态</strong><p>{{status.unlocked?'当前已解锁，请确保恢复包已离线保存。':'需要手动解锁后才能执行任务。'}}</p></div><button class="icon-button" @click="navigate('security')"><ArrowUpRight :size="17"/></button></div><div class="health-item"><span class="health-dot info"/><div><strong>恢复演练</strong><p>上传完成与全量读取检查是独立状态。建议定期在新目录恢复并核对内容。</p></div></div></section></div>
          <section class="panel"><div class="panel-head"><h2>存储账号<span class="label-sub">Storage capacity</span></h2><button class="text-button" @click="navigate('accounts')">管理账号<ArrowRight :size="14"/></button></div><div v-if="!data.accounts.length" class="empty compact"><Cloud :size="26"/><p>尚未连接存储账号。完成授权与访问验证后可分配容量。</p></div><div v-else class="capacity-overview"><div v-for="account in data.accounts.slice(0,4)" :key="account.id" class="capacity-row"><span class="account-icon"><Cloud v-if="account.backend!=='local'" :size="21"/><HardDrive v-else :size="21"/></span><div><strong>{{account.name}}</strong><small>{{account.drive_name||'待选择 Drive'}}</small></div><div class="capacity-track"><div class="thin-meter"><span :style="{width:usage(account)+'%'}"/></div><small>{{bytes(account.project_used_bytes)}} / {{bytes(account.budget_bytes)}} 项目预算</small></div><span class="badge" :class="tone(account.status)">{{statusLabel(account.status)}}</span></div></div><div class="panel-foot"><CircleHelp :size="14"/>容量用二进制单位 GiB / TiB 展示；容量分摊不等于数据多副本。</div></section>
        </template>

        <template v-if="selectedNav==='accounts'">
          <div class="inline-toolbar"><div class="search-input"><Search :size="17"/><input v-model="accountSearch" placeholder="搜索账号、Drive 名称或 ID"/></div><span class="text-secondary">共 {{totals.accounts??0}} 个账号</span></div>
          <div v-if="!data.accounts.length" class="panel empty large"><div class="empty-icon"><Cloud :size="30"/></div><h3>连接你的第一个 OneDrive</h3><p>授权后显式选择 Drive，验证根目录与测试目录访问，再设置容量预算。</p><button class="button primary" :disabled="!status.unlocked" @click="openAccount()"><Plus :size="17"/>添加存储账号</button></div>
          <div v-else class="account-grid"><article v-for="account in filteredAccounts" :key="account.id" class="panel account-card"><div class="account-card-head"><span class="account-icon"><Cloud v-if="account.backend!=='local'" :size="24"/><HardDrive v-else :size="24"/></span><div><h2>{{account.name}}</h2><p>{{account.backend==='local'?'本地联调存储':'Microsoft OneDrive'}}</p></div><span class="badge" :class="account.enabled?tone(account.status):'neutral'">{{account.enabled?statusLabel(account.status):'已停用'}}</span></div><div class="drive-info"><span>{{account.drive_name||'尚未选择 Drive'}}</span><small>{{account.drive_type||account.backend}} · {{account.region||'未提供区域'}}</small><code>{{account.drive_id||account.local_path||'授权后显示稳定标识'}}</code></div><div class="account-capacity"><div><strong>{{bytes(account.project_used_bytes)}}</strong><span>项目占用 / {{bytes(account.budget_bytes)}} 预算</span></div><div class="thin-meter"><span :class="{warn:usage(account)>85}" :style="{width:usage(account)+'%'}"/></div></div><dl class="account-details"><div><dt>云端总容量</dt><dd>{{account.quota_at?bytes(account.total_bytes):'待查询'}}</dd></div><div><dt>云端已用</dt><dd>{{account.quota_at?bytes(account.used_bytes):'待查询'}}</dd></div><div><dt>云端剩余</dt><dd>{{account.quota_at?bytes(account.free_bytes):'待查询'}}</dd></div><div><dt>维护预留</dt><dd>{{bytes(account.maintenance_reserve_bytes)}}</dd></div></dl><p class="quota-time"><Clock3 :size="12"/>配额查询：{{date(account.quota_at)}}</p><div class="account-card-actions"><button class="button small secondary" @click="openAccount(account)">{{account.verified?'重新授权 / 验证':'继续设置'}}</button><button class="text-button" :disabled="busy" @click="toggleEntity('accounts',account)">{{account.enabled?'停用':'启用'}}</button><button class="icon-button" title="修改名称与容量预算" @click="editAccountSettings(account)"><Settings2 :size="15"/></button><button class="icon-button" title="刷新配额与项目占用" :disabled="busy||!account.verified||!status.unlocked" @click="refreshAccountQuota(account)"><RefreshCw :size="15"/></button><button class="icon-button" title="删除账号配置" @click="removeEntity('accounts',account)"><Trash2 :size="15"/></button></div></article></div>
          <div class="small-note"><CircleHelp :size="17"/><span>停用账号只停止新分配，已有数据保留。OneDrive Personal 为首版验证范围；企业版与 SharePoint 的兼容性以真实测试为准。</span></div>
        </template>

        <template v-if="selectedNav==='pools'">
          <div v-if="!data.pools.length" class="panel empty large"><div class="empty-icon"><Database :size="30"/></div><h3>为备份建立存储池</h3><p>选择已验证账号。默认要求控制资料写入两个不同的 Drive。</p><button class="button primary" @click="openForm('pool')"><Plus :size="17"/>新建存储池</button></div>
          <div v-else class="pool-grid"><article v-for="pool in data.pools" :key="pool.id" class="panel pool-card"><div class="panel-head"><h2><Database :size="21"/>{{pool.name}}</h2><button class="icon-button" title="编辑存储池" @click="openForm('pool',pool)"><Settings2 :size="17"/></button></div><div class="pool-metrics"><div><small>账号成员</small><strong>{{pool.account_ids?.length??0}}<span> 个</span></strong></div><div><small>分片规划参考</small><strong>{{bytes(pool.shard_target_bytes)}}</strong></div></div><div class="pool-members"><span v-for="id in pool.account_ids" :key="id"><Cloud :size="14"/>{{accountName(id)}}</span></div><div class="pool-policy"><ShieldCheck :size="17"/><p>控制目录副本要求<strong>{{pool.catalog_replicas}} 个不同 Drive</strong><small>这是加密控制资料副本，不代表业务数据多副本。</small></p></div><div class="panel-foot"><span>稳定归属 · 新数据优先使用空闲容量</span><button class="icon-button" title="删除池配置" @click="removeEntity('pools',pool)"><Trash2 :size="15"/></button></div></article></div>
        </template>

        <template v-if="selectedNav==='sources'">
          <div class="small-note"><FolderOpen :size="17"/><span>目录来自运行服务的服务器，以及部署者允许挂载的范围。此处不浏览你的个人电脑。</span></div>
          <section class="panel"><div class="panel-head"><h2>服务器备份目录</h2><span class="tiny-label">{{totals.sources??0}} 个源</span></div><div v-if="!data.sources.length" class="empty large"><div class="empty-icon"><FolderOpen :size="30"/></div><h3>添加需要保护的目录</h3><p>系统会记录稳定逻辑 ID，并检查目录边界与挂载身份。</p><button class="button primary" @click="openForm('source')"><Plus :size="17"/>添加备份源</button></div><div v-else class="table-scroll"><table><thead><tr><th>目录 / 逻辑源</th><th>范围设置</th><th>关联计划</th><th>操作</th></tr></thead><tbody><tr v-for="source in data.sources" :key="source.id"><td><div class="table-name"><span class="folder-icon"><Folder :size="22"/></span><div><strong>{{source.name}}</strong><code>{{source.path}}</code><small>ID · {{source.id}}</small></div></div></td><td><span class="badge neutral">{{source.one_file_system?'不跨文件系统':'允许跨文件系统'}}</span><small class="cell-note">{{source.include_hidden?'包含隐藏文件':'排除隐藏文件'}} · {{source.excludes?.length??0}} 条排除规则</small><small class="cell-note">{{source.max_file_bytes?`单文件上限 ${bytes(source.max_file_bytes)}`:'无单文件大小限制'}}</small></td><td><span v-if="catalog.plans.some(p=>p.source_ids?.includes(source.id))" class="badge success">已有计划</span><span v-else class="badge warning">待关联计划</span></td><td><div class="row-actions"><button class="text-button" @click="openForm('source',source)">编辑</button><button class="icon-button" title="删除备份源" @click="removeEntity('sources',source)"><Trash2 :size="15"/></button></div></td></tr></tbody></table></div></section>
        </template>

        <template v-if="selectedNav==='plans'">
          <div v-if="!data.plans.length" class="panel empty large"><div class="empty-icon"><Clock3 :size="30"/></div><h3>让备份按时发生</h3><p>选择目录与存储池，配置 Cron、时区和历史保留数量。</p><button class="button primary" :disabled="recoveryMode" @click="openForm('plan')"><Plus :size="17"/>新建备份计划</button></div>
          <div v-else class="plan-list"><article v-for="plan in data.plans" :key="plan.id" class="panel plan-card"><div class="plan-header"><span class="plan-icon"><Clock3 :size="23"/></span><div><h2>{{plan.name}}<span class="badge" :class="plan.enabled?'success':'neutral'">{{plan.enabled?'已启用':'已暂停'}}</span></h2><p>{{poolName(plan.pool_id)}} · {{plan.source_ids?.length??0}} 个备份源</p></div><div class="row-actions"><button class="button small secondary" :disabled="busy||!status.unlocked||recoveryMode" @click="startPlan(plan,'preview')"><SlidersHorizontal :size="15"/>分配预览</button><button class="button small primary" :disabled="busy||!status.unlocked||recoveryMode" @click="startPlan(plan,'run')"><ArrowRight :size="15"/>立即备份</button></div></div><div class="plan-details"><div><span>执行时间</span><strong><code>{{plan.schedule}}</code></strong><small>{{plan.timezone}}</small></div><div><span>备份目录</span><strong>{{plan.source_ids?.map(sourceName).join('、')||'—'}}</strong><small>{{plan.excludes?.length??0}} 条计划排除规则</small></div><div><span>保留策略</span><strong>每日 {{plan.retention?.daily??0}} · 每周 {{plan.retention?.weekly??0}} · 每月 {{plan.retention?.monthly??0}}</strong><small>受保护恢复点独立保留</small></div><div><span>资源限制</span><strong>{{plan.bandwidth_kib?`${plan.bandwidth_kib} KiB/s`:'不限制带宽'}}</strong><small>失败重试 {{plan.retry_count??0}} 次</small></div></div><div class="plan-footer"><div><Clock3 :size="14"/><span>{{plan.timezone}} 接下来三次：{{(plan.next_runs??plan.next_executions??[]).map((value: string)=>dateInZone(value,plan.timezone)).join(' · ')||'暂无已计算的执行时间'}}</span></div><div class="row-actions"><button class="text-button" :disabled="recoveryMode" @click="toggleEntity('plans',plan)">{{plan.enabled?'暂停':'启用'}}</button><button class="text-button" :disabled="recoveryMode" @click="openForm('plan',plan)">编辑</button><button class="icon-button" title="删除计划" :disabled="recoveryMode" @click="removeEntity('plans',plan)"><Trash2 :size="15"/></button></div></div></article></div>
          <div class="small-note"><CircleHelp :size="17"/><span>同一计划运行期间的新触发最多合并为一次待执行任务。目录备份记录开始到结束的时间区间；持续写入的数据库应先通过应用导出或一致性快照处理。</span></div>
        </template>

        <template v-if="selectedNav==='restore'">
          <div v-if="!data.points.length" class="panel empty large"><div class="empty-icon"><ArrowDownToLine :size="30"/></div><h3>等待第一个完整恢复点</h3><p>只有必要分片与加密控制资料提交成功，才会发布完整恢复点。</p><button v-if="recoveryMode" class="button secondary" :disabled="busy||!status.unlocked" @click="maintenance('/security/discover',{})"><RefreshCw :size="16"/>发现已有云端备份</button></div>
          <div v-else class="recovery-layout"><section class="panel recovery-timeline"><div class="panel-head"><h2>历史恢复点</h2><span class="tiny-label">{{totals.points}}</span></div><button v-for="point in data.points" :key="point.id" class="point-row" :class="{selected:selectedPoint?.id===point.id}" @click="selectPoint(point)"><span class="point-mark"><Files :size="17"/></span><div><strong>{{point.name||planName(point.plan_id)}}</strong><small>{{date(point.finished_at||point.started_at)}}</small><p>{{point.file_count??'—'}} 个条目 · {{bytes(point.logical_bytes)}}</p><span class="badge" :class="tone(point.status)">{{statusLabel(point.status)}}</span><span v-if="point.protected" class="protected-note"><ShieldCheck :size="12"/>已保护</span></div><ChevronRight :size="14"/></button></section><section class="panel recovery-browser"><div v-if="!selectedPoint" class="empty large"><Files :size="32"/><h3>选择一个恢复点</h3><p>浏览历史目录、搜索文件，预检查后恢复到新位置。</p></div><template v-else><div class="panel-head"><div><h2>{{selectedPoint.name||planName(selectedPoint.plan_id)}}</h2><small class="text-secondary">{{date(selectedPoint.started_at)}} — {{date(selectedPoint.finished_at)}}</small></div><button class="button small secondary" @click="protectPoint(selectedPoint)"><ShieldCheck :size="15"/>{{selectedPoint.protected?'取消保护':'保护恢复点'}}</button></div><div class="file-toolbar"><select v-model="filesState.source" @change="action(()=>loadFiles(0))"><option value="">全部备份源</option><option v-for="source in catalog.sources" :key="source.id" :value="source.id">{{source.name}}</option></select><div class="search-input"><Search :size="15"/><input v-model="filesState.search" placeholder="搜索历史路径" @keyup.enter="action(()=>loadFiles(0))"/></div><button class="button small secondary" @click="action(()=>loadFiles(0))">搜索</button></div><div class="path-bar"><FolderOpen :size="15"/><input v-model="filesState.prefix" placeholder="路径前缀（留空显示全部）" @keyup.enter="action(()=>loadFiles(0))"/><button class="text-button" @click="action(()=>loadFiles(0))">打开</button></div><div class="file-scope"><span>{{selectedFiles.length?'将恢复已选择的目录或文件。':restoreForm.source_ids.length?'将恢复选定的完整备份源。':'未选择条目时恢复整个恢复点；勾选后按选定范围恢复。'}}</span><button v-if="selectedFiles.length" class="text-button" @click="selectedFiles=[];restorePreview=null">清空 {{selectedFiles.length}} 项</button></div><div class="table-scroll"><table class="file-table"><thead><tr><th></th><th>路径</th><th>备份源</th><th>大小</th><th></th></tr></thead><tbody><tr v-for="file in filesState.items" :key="`${file.source_id}/${file.path}`"><td><input type="checkbox" :checked="hasFile(file)" @change="toggleFile(file)" /></td><td><div class="file-name"><Folder v-if="['directory','dir'].includes(file.kind)" :size="17"/><File v-else :size="17"/><span class="filename">{{file.path}}</span></div></td><td><small>{{sourceName(file.source_id)}}</small></td><td>{{bytes(file.size)}}</td><td><button v-if="['directory','dir'].includes(file.kind)" class="text-button" @click="filesState.source=file.source_id;filesState.prefix=file.path?file.path+'/':'';action(()=>loadFiles(0))">打开<ChevronRight :size="13"/></button></td></tr><tr v-if="!filesState.items.length"><td colspan="5" class="empty-cell">此范围没有文件条目。</td></tr></tbody></table></div><div class="pagination"><span>共 {{filesState.total}} 条 · 已选 {{selectedFiles.length}} 项</span><div><button class="icon-button" :disabled="filesState.offset===0" @click="action(()=>loadFiles(filesState.offset-pageSize))"><ChevronLeft :size="17"/></button><span>{{Math.floor(filesState.offset/pageSize)+1}}</span><button class="icon-button" :disabled="filesState.offset+pageSize>=filesState.total" @click="action(()=>loadFiles(filesState.offset+pageSize))"><ChevronRight :size="17"/></button></div></div><div class="restore-options"><label class="field">整体恢复范围<select :value="restoreForm.source_ids[0]||''" @change="restoreForm.source_ids=($event.target as HTMLSelectElement).value?[($event.target as HTMLSelectElement).value]:[];selectedFiles=[];restorePreview=null"><option value="">整个恢复点</option><option v-for="source in catalog.sources" :key="source.id" :value="source.id">整个备份源 · {{source.name}}</option></select><small>勾选目录或文件后，以选定条目为恢复范围。</small></label><label class="field">服务器恢复目标<input v-model="restoreForm.target" placeholder="输入允许范围内的新目录绝对路径" @input="restorePreview=null"/><small>允许范围：{{status.restore_roots?.join('、')||'尚未配置恢复根目录'}}</small></label><div class="restore-checks"><label class="check-label"><input v-model="restoreForm.overwrite" type="checkbox" @change="restorePreview=null"/>允许覆盖冲突文件</label><label class="check-label"><input v-model="restoreForm.allow_partial" type="checkbox" @change="restorePreview=null"/>接受明确的部分恢复</label></div><button class="button primary" :disabled="busy||!restoreForm.target||!status.unlocked" @click="previewRestore"><Search :size="17"/>预检查恢复范围</button></div></template></section></div>
        </template>

        <template v-if="selectedNav==='tasks'">
          <div class="inline-toolbar"><div class="segmented"><button :class="{active:taskFilter==='all'}" @click="taskFilter='all'">全部任务</button><button :class="{active:taskFilter==='running'}" @click="taskFilter='running'">执行中</button><button :class="{active:taskFilter==='complete'}" @click="taskFilter='complete'">已完成</button><button :class="{active:taskFilter==='failed'}" @click="taskFilter='failed'">异常</button></div><span class="live-indicator"><i/>每 5 秒刷新</span></div>
          <section class="panel"><div v-if="!filteredTasks.length" class="empty large"><div class="empty-icon"><ListChecks :size="29"/></div><h3>{{data.tasks.length?'当前筛选下没有任务':'暂无任务记录'}}</h3><p>任务在后台运行，关闭浏览器不会中断。重新连接会获取持久化状态。</p></div><div v-else class="table-scroll"><table class="task-table"><thead><tr><th>任务</th><th>状态 / 阶段</th><th>处理统计</th><th>开始时间</th><th>操作</th></tr></thead><tbody><tr v-for="task in filteredTasks" :key="task.id"><td><strong class="block">{{taskKind(task.kind)}}</strong><small class="cell-note">{{task.name||planName(task.plan_id)||task.id.slice(0,12)}}</small><code class="muted-code">{{task.id.slice(0,12)}}</code></td><td><span class="badge" :class="tone(task.status)">{{statusLabel(task.status)}}</span><small class="cell-note">{{statusLabel(task.stage)}}</small><div v-if="task.progress!=null" class="task-progress"><span :style="{width:`${Math.min(100,Number(task.progress)>1?Number(task.progress):Number(task.progress)*100)}%`}"/></div><small v-if="task.error" class="task-error">{{task.error}}</small></td><td><small class="stat-line">扫描 <strong>{{bytes(task.scanned_bytes)}}</strong></small><small class="stat-line">上传 <strong>{{bytes(task.uploaded_bytes)}}</strong></small><small class="stat-line">云端净增长 <strong>{{bytes(task.cloud_growth_bytes)}}</strong></small></td><td><small>{{date(task.started_at)}}</small><small v-if="task.finished_at" class="cell-note">结束 {{date(task.finished_at)}}</small></td><td><div class="row-actions"><button class="text-button" @click="openTask(task)">详情与日志</button><button v-if="isActive(task.status)" class="icon-button" title="取消任务" :disabled="busy" @click="cancelTask(task)"><Square :size="14"/></button></div></td></tr></tbody></table></div></section>
          <div class="small-note"><Activity :size="17"/><span>扫描处理量、实际上传量与云端净增长量分别统计。完成备份不表示所有数据已被全量读回验证；检查任务独立显示结果。</span></div>
        </template>

        <template v-if="selectedNav==='security'">
          <div class="security-grid"><section class="panel security-card"><span class="security-icon"><KeyRound :size="25"/></span><h2>密钥与恢复包</h2><p>离线保存加密恢复包，在原服务器与状态目录丢失时解锁并发现已有备份。</p><div class="security-facts"><div><span>库标识</span><code>{{status.vault_id}}</code></div><div><span>运行模式</span><strong>{{recoveryMode?'恢复节点':'单活跃写入节点'}}</strong></div><div><span>密钥状态</span><span class="badge" :class="status.unlocked?'success':'warning'">{{status.unlocked?'已解锁':'已锁定'}}</span></div></div><div class="row-actions"><button class="button primary small" :disabled="!status.unlocked" @click="form.password='';modal='export'"><Download :size="15"/>导出恢复包</button><button v-if="status.unlocked" class="button secondary small" :disabled="busy" @click="lock"><LockKeyhole :size="15"/>锁定</button><button v-else class="button secondary small" @click="form.password='';modal='unlock'">解锁</button></div><div class="small-note"><Shield :size="16"/><span>恢复包默认不包含长期 OAuth Token。异机恢复需要重新授权账号。自动解锁依赖外部受限 Secret，不能防御宿主机高权限被攻破。</span></div></section><section class="panel security-card"><span class="security-icon mint"><Search :size="25"/></span><h2>发现云端备份</h2><p>从账号中的加密控制目录验证提交记录，重建本地索引与历史恢复点。</p><ol class="steps-list"><li><span>1</span>导入恢复包，建立恢复节点</li><li><span>2</span>重新授权原备份使用的账号</li><li><span>3</span>发现目录，再选择恢复范围</li></ol><button class="button secondary small" :disabled="busy||!status.unlocked" @click="maintenance('/security/discover',{})"><RefreshCw :size="15"/>发现并重建索引</button><p class="text-secondary fine">此操作不会初始化或覆盖已有云端仓库。</p></section></div>
          <section class="panel"><div class="panel-head"><h2>仓库完整性检查</h2><span class="tiny-label">{{totals.repos??0}} 个仓库</span></div><div class="maintenance-content"><div class="repository-picker"><p>选择仓库（不选时检查所有可用仓库）</p><label v-for="repo in data.repos" :key="repo.id" class="check-label repo-option"><input v-model="repositorySelection" type="checkbox" :value="repo.id"/><div><strong>{{repo.name||repo.id}}</strong><small>{{accountName(repo.account_id)}} · {{repo.path||repo.remote_path}} · {{statusLabel(repo.status)}}</small></div></label><p v-if="!data.repos.length" class="text-secondary">尚无已登记仓库。首次备份或云端发现后会显示。</p></div><div class="check-controls"><label class="field">检查范围<select v-model="maintenanceForm.mode"><option value="structure">仓库结构检查</option><option value="sample">数据抽查</option><option value="full">全量读取检查</option></select></label><label v-if="maintenanceForm.mode==='sample'" class="field">抽查比例<input v-model="maintenanceForm.sample" placeholder="10%" pattern="[0-9]+%" /></label><p>{{maintenanceForm.mode==='structure'?'检查仓库结构、快照与索引引用，不读取验证全部数据。':maintenanceForm.mode==='sample'?'读取并校验选定比例的数据，结果只覆盖被抽查的范围。':'读取并验证全部数据，可能产生较大下载流量和较长耗时。'}}</p><button class="button secondary" :disabled="busy||!status.unlocked||!data.repos.length" @click="maintenance('/maintenance/check',{repository_ids:repositorySelection,mode:maintenanceForm.mode,sample:maintenanceForm.sample})"><ShieldCheck :size="16"/>开始检查</button></div></div></section>
          <div class="security-grid"><section class="panel security-card"><span class="security-icon orange"><Trash2 :size="23"/></span><h2>历史保留与清理</h2><p>按全局恢复点计算保留集合。手动保护的恢复点和有效引用的数据不得清理。</p><label class="field">选择备份计划<select v-model="maintenanceForm.plan_id"><option value="" disabled>选择计划</option><option v-for="plan in catalog.plans" :key="plan.id" :value="plan.id">{{plan.name}}</option></select></label><button class="button secondary small" :disabled="busy||!maintenanceForm.plan_id||recoveryMode||!status.unlocked" @click="previewRetention"><Search :size="15"/>预览清理范围</button><p class="text-secondary fine">先显示删除预览，经明确确认后执行。空间不足不会自动突破保留策略。</p></section><section class="panel security-card"><span class="security-icon"><ArrowRight :size="24"/></span><h2>受控整仓迁移</h2><p>将整个仓库复制到新的账号，校验后提交位置映射。旧副本保留用于观察。</p><label class="field">迁移仓库<select v-model="maintenanceForm.repository_id" @change="maintenanceForm.old_location_index='';maintenanceForm.target_account_id=''"><option value="" disabled>选择已登记仓库</option><option v-for="repo in data.repos" :key="repo.id" :value="repo.id">{{repo.name||repo.id}} · {{accountName(repo.account_id)}}</option></select></label><label class="field">目标账号<select v-model="maintenanceForm.target_account_id"><option value="" disabled>选择已验证并启用的账号</option><option v-for="account in catalog.accounts.filter(a=>a.verified&&a.enabled&&a.id!==data.repos.find(r=>r.id===maintenanceForm.repository_id)?.account_id)" :key="account.id" :value="account.id">{{account.name}} · 剩余 {{bytes(account.free_bytes)}}</option></select></label><button class="button secondary small" :disabled="busy||!maintenanceForm.repository_id||!maintenanceForm.target_account_id||recoveryMode||!status.unlocked" @click="migrate"><ArrowRight :size="15"/>检查并迁移</button><div class="old-copy-controls"><h3>旧副本观察后清理</h3><p>只允许选择已登记的旧位置。当前有效位置会先进行全量读取检查，通过后才删除旧副本。</p><label v-if="oldRepositoryLocations.length" class="field">选择要删除的旧位置<select v-model="maintenanceForm.old_location_index"><option value="" disabled>显式选择旧仓库副本</option><option v-for="location in oldRepositoryLocations" :key="location.index" :value="location.index">{{accountName(location.account_id)}} · {{location.path}}{{location.status==='cleanup_pending'?' · 清理待重试':''}}</option></select><small>当前有效位置与已删除位置不会出现在列表中。</small></label><p v-else class="text-secondary fine">{{maintenanceForm.repository_id?'此仓库没有可清理的旧位置。':'选择仓库后，查看已登记的旧副本。'}}</p><button class="button secondary small" :disabled="busy||maintenanceForm.old_location_index===''||!oldRepositoryLocations.some((location:any)=>location.index===Number(maintenanceForm.old_location_index))||recoveryMode||!status.unlocked" @click="cleanupOldLocation"><Trash2 :size="15"/>确认清理旧副本</button></div></section></div><section v-if="status.cache_max_bytes!=null||status.log_max_rows!=null||status.maintenance_window!=null" class="panel runtime-limits"><div class="panel-head"><h2>部署运行限制</h2><span class="tiny-label">由服务器配置管理</span></div><div class="runtime-limits-grid"><div v-if="status.cache_max_bytes!=null"><span>引擎缓存上限</span><strong>{{bytes(status.cache_max_bytes)}}</strong><small>缓存受部署资源预算约束。</small></div><div v-if="status.log_max_rows!=null"><span>日志记录上限</span><strong>{{Number(status.log_max_rows).toLocaleString('zh-CN')}}<em> 条</em></strong><small>超过上限时按服务保留规则处理。</small></div><div v-if="status.maintenance_window!=null"><span>维护时间窗口</span><strong>{{status.maintenance_window||'不限时段'}}</strong><small>{{status.maintenance_timezone||status.timezone||'时区由服务器配置'}}</small></div></div></section><section class="panel audit-panel"><div class="panel-head"><h2>操作审计</h2><span class="tiny-label">{{totals.audit??0}} 条事件</span></div><div v-if="!data.audit.length" class="empty compact"><p>尚无审计事件。敏感操作仅记录动作与资源标识，不包含凭据。</p></div><div v-else class="table-scroll"><table><thead><tr><th>操作</th><th>资源</th><th>时间</th></tr></thead><tbody><tr v-for="event in data.audit" :key="event.id"><td>{{auditLabel(event.action)}}</td><td><code>{{event.resource||'—'}}</code></td><td>{{date(event.at)}}</td></tr></tbody></table></div><div v-if="(totals.audit??0)>pageSize" class="pagination"><span>共 {{totals.audit}} 条</span><div><button class="icon-button" :disabled="!(offsets.audit??0)" @click="changePage('audit',-1)"><ChevronLeft :size="17"/></button><span>{{Math.floor((offsets.audit??0)/pageSize)+1}}</span><button class="icon-button" :disabled="(offsets.audit??0)+pageSize>=(totals.audit??0)" @click="changePage('audit',1)"><ChevronRight :size="17"/></button></div></div></section>
        </template>

        <div v-if="['accounts','pools','sources','plans','tasks','restore'].includes(selectedNav) && (totals[selectedNav==='restore'?'points':selectedNav]??0)>pageSize" class="pagination"><span>共 {{totals[selectedNav==='restore'?'points':selectedNav]}} 条</span><div><button class="icon-button" :disabled="!(offsets[selectedNav==='restore'?'points':selectedNav]??0)" @click="changePage(selectedNav==='restore'?'points':selectedNav,-1)"><ChevronLeft :size="18"/></button><span>{{Math.floor((offsets[selectedNav==='restore'?'points':selectedNav]??0)/pageSize)+1}}</span><button class="icon-button" :disabled="(offsets[selectedNav==='restore'?'points':selectedNav]??0)+pageSize>=(totals[selectedNav==='restore'?'points':selectedNav]??0)" @click="changePage(selectedNav==='restore'?'points':selectedNav,1)"><ChevronRight :size="18"/></button></div></div>
        <footer class="workspace-footer"><span>VaultPilot · 自托管加密备份</span><span><ShieldCheck :size="13"/>让备份可追溯，让恢复可验证</span></footer>
      </main>
    </div>

    <div v-if="modal" class="modal-backdrop" @click.self="closeModal"><section class="modal" :class="{'wide': ['account','plan','task','restore-preview','retention-preview','browse'].includes(modal)}" role="dialog" aria-modal="true" :aria-label="modal==='confirm'?confirmTitle:'操作窗口'"><div class="modal-head"><div><span class="eyebrow">{{modal==='task'?'TASK DETAILS':modal==='account'?'CONNECT STORAGE':'VAULTPILOT'}}</span><h2>{{modal==='account'?'连接存储账号':modal==='account-settings'?'账号名称与容量预算':modal==='pool'?(form.id?'编辑存储池':'新建存储池'):modal==='source'?(form.id?'编辑备份源':'添加备份源'):modal==='plan'?(form.id?'编辑备份计划':'新建备份计划'):modal==='browse'?'选择服务器目录':modal==='task'?'任务详情与日志':modal==='unlock'?'解锁备份库':modal==='export'?'导出加密恢复包':modal==='restore-preview'?'恢复预检查':modal==='retention-preview'?'历史清理预览':confirmTitle}}</h2></div><button class="icon-button" title="关闭" :disabled="busy" @click="closeModal"><X :size="21"/></button></div><div class="modal-body"><div v-if="error" class="alert danger"><Shield :size="17"/><div>{{error.message}}<small>{{error.code}}</small></div><button class="icon-button" @click="error=null"><X :size="14"/></button></div>
      <form v-if="modal==='account-settings'" @submit.prevent="saveAccountSettings"><label class="field">账号名称<input v-model="form.name" required maxlength="100"/></label><label class="field">项目预算 (GiB)<input v-model.number="form.budget_gib" type="number" min="1" required/></label><div class="form-grid"><label class="field">云端安全预留 (GiB)<input v-model.number="form.reserve_gib" type="number" min="0" required/></label><label class="field">项目维护预留 (GiB)<input v-model.number="form.maintenance_gib" type="number" min="0" required/></label></div><div class="small-note"><HardDrive :size="16"/><span>容量调整只影响新分配与任务容量校验，不会搬迁或删除已有数据。维护预留应小于项目预算。</span></div><div class="modal-actions"><button type="button" class="button secondary" @click="closeModal">取消</button><button class="button primary" :disabled="busy">保存设置</button></div></form><template v-if="modal==='account'"><div class="wizard-steps"><span v-for="(text,index) in ['账号信息','微软授权','Drive 与验证','完成']" :key="text" :class="{active:accountStep===index+1,done:accountStep>index+1}"><i><Check v-if="accountStep>index+1" :size="13"/><template v-else>{{index+1}}</template></i>{{text}}</span></div><form v-if="accountStep===1" @submit.prevent="createAccount"><label class="field">账号名称<input v-model="form.name" required maxlength="100" placeholder="例如：个人 OneDrive · 主账号"/></label><label v-if="status.allow_local" class="field">存储类型<select v-model="form.backend"><option value="onedrive">Microsoft OneDrive</option><option value="local">本地存储 · 真实引擎联调</option></select></label><label v-if="form.backend==='local'" class="field">服务器本地仓库目录<input v-model="form.local_path" required placeholder="输入允许范围内的绝对路径"/><small>仅在部署配置允许本地后端时提供，用于真实 Restic 联调。</small></label><button class="button primary" :disabled="busy">创建账号并继续<ArrowRight :size="16"/></button></form><template v-if="accountStep===2"><RcloneAuthorization v-if="activeAccount" :key="activeAccount.id" :account="activeAccount" :custom-o-auth="status.oauth_configured" :rclone-available="status.engines?.rclone" @authorized="onRcloneAuthorized" @custom="authorizeAccount" @resume="loadDrives"/></template><template v-if="accountStep===3"><template v-if="activeAccount?.backend!=='local'"><button class="text-button" @click="accountStep=2;chosenDrive=''">重新授权此账号<ArrowUpRight :size="14"/></button><p class="section-description">选择实际存放备份的 Drive。系统不会自动选择第一个条目；元数据专用入口可能不具备备份所需访问能力。</p><div v-if="!drives.length" class="empty compact"><p>尚无可选择的 Drive。</p><button class="button secondary small" @click="loadDrives">重新读取列表</button></div><label v-for="drive in drives" :key="drive.id" class="drive-option" :class="{selected:chosenDrive===drive.id,unsupported:drive.supported===false}"><input v-model="chosenDrive" type="radio" :value="drive.id" :disabled="drive.supported===false"/><Cloud :size="21"/><div><strong>{{drive.name||drive.id}}</strong><small>{{drive.drive_type||drive.driveType||drive.type}} · {{drive.id}}<span v-if="drive.supported===false"> · 当前类型尚未验证兼容性</span></small></div></label></template><div class="form-grid three"><label class="field">项目预算 (GiB)<input v-model.number="accountBudget.budget" type="number" min="1" step="1" required/></label><label class="field">云端预留 (GiB)<input v-model.number="accountBudget.reserve" type="number" min="0" step="1" required/></label><label class="field">维护预留 (GiB)<input v-model.number="accountBudget.maintenance" type="number" min="0" step="1" required/></label></div><div class="small-note"><ShieldCheck :size="16"/><span>验证将检查根目录访问并在项目专用测试目录进行读写。只有通过验证才能加入存储池。</span></div><button class="button primary full" :disabled="busy||!chosenDrive&&activeAccount?.backend!=='local'" @click="verifyAccount"><LoaderCircle v-if="busy" class="spin" :size="16"/><ShieldCheck v-else :size="16"/>验证访问并保存预算</button></template><template v-if="accountStep===4"><div class="success-state"><span><Check :size="34"/></span><h3>账号访问验证通过</h3><p>「{{activeAccount?.name}}」可以加入存储池。<br>业务数据容量分配与控制资料副本独立配置。</p></div><div class="modal-actions"><button class="button secondary" @click="modal=''">完成</button><button class="button primary" @click="modal='';navigate('pools');openForm('pool')">加入存储池<ArrowRight :size="16"/></button></div></template></template>

      <form v-if="modal==='pool'" @submit.prevent="saveForm"><label class="field">存储池名称<input v-model="form.name" required maxlength="100" placeholder="例如：家庭文档备份池"/></label><label class="field">账号成员<small>仅展示已验证并启用的账号。</small></label><div class="checkbox-list"><label v-for="account in catalog.accounts.filter(a=>a.verified&&a.enabled)" :key="account.id" class="check-label"><input v-model="form.account_ids" type="checkbox" :value="account.id"/><span>{{account.name}} <small>{{bytes(account.budget_bytes)}} 预算</small></span></label><p v-if="!catalog.accounts.some(a=>a.verified&&a.enabled)" class="text-secondary">先添加并验证存储账号。</p></div><div class="form-grid"><label class="field">控制目录副本数量<input v-model.number="form.catalog_replicas" type="number" min="1" required/><small>正式部署建议至少两个不同 Drive；不会静默降低要求。</small></label><label class="field">分片目标规模 (GiB)<input v-model.number="form.shard_target_gib" type="number" min="1" required/><small>源数据规划参考，不是实际仓库占用上限。</small></label></div><div class="modal-actions"><button type="button" class="button secondary" @click="closeModal">取消</button><button class="button primary" :disabled="busy||!form.account_ids?.length">保存存储池</button></div></form>

      <form v-if="modal==='source'" @submit.prevent="saveForm"><label class="field">备份源名称<input v-model="form.name" required maxlength="100" placeholder="例如：文档与项目"/></label><label class="field">服务器目录<div class="input-with-button"><input v-model="form.path" required placeholder="允许挂载范围内的绝对路径"/><button type="button" class="button secondary small" @click="openBrowser"><FolderOpen :size="16"/>选择</button></div><small>允许范围：{{status.source_roots?.join('、')||'尚未配置源目录挂载'}}</small></label><label class="field">排除规则（每行一条）<textarea v-model="form.excludes_text" rows="4" placeholder="例如：&#10;**/.cache/**&#10;**/*.tmp"/></label><label class="field">单文件大小限制 (MiB)<input v-model.number="form.max_file_mib" type="number" min="0"/><small>0 表示不限制；超过限制的文件不纳入此备份源。</small></label><div class="restore-checks"><label class="check-label"><input v-model="form.include_hidden" type="checkbox"/>包含隐藏文件</label><label class="check-label"><input v-model="form.one_file_system" type="checkbox"/>不跨越文件系统边界</label></div><div class="small-note"><Folder :size="16"/><span>源目录登记时检查路径与挂载身份。符号链接保存链接本身，避免递归追踪目标。</span></div><div class="modal-actions"><button type="button" class="button secondary" @click="closeModal">取消</button><button class="button primary" :disabled="busy">保存备份源</button></div></form>

      <template v-if="modal==='browse'"><p class="section-description">这里是服务器已授权挂载的目录。选择目录后返回备份源配置。</p><div class="path-bar"><FolderOpen :size="17"/><span>{{browseState.path||'允许的挂载入口'}}</span><button v-if="browseState.path" class="text-button" @click="browse(browseState.path.slice(0,browseState.path.lastIndexOf('/'))||'/')">上级</button></div><div class="browse-list"><button v-for="entry in browseState.items" :key="entry.path||entry.name" @click="browse(entry.path||`${browseState.path}/${entry.name}`)"><Folder :size="21"/><span>{{entry.name||entry.path}}</span><ChevronRight :size="16"/></button><p v-if="!browseState.items.length" class="empty-cell">此目录没有可浏览的子目录。</p></div><div class="pagination"><span>共 {{browseState.total}} 个目录</span><div><button class="icon-button" :disabled="browseState.offset===0" @click="browse(browseState.path,browseState.offset-pageSize)"><ChevronLeft :size="17"/></button><button class="icon-button" :disabled="browseState.offset+pageSize>=browseState.total" @click="browse(browseState.path,browseState.offset+pageSize)"><ChevronRight :size="17"/></button></div></div><div class="modal-actions"><button class="button secondary" @click="modal='source'">返回</button><button class="button primary" :disabled="!browseState.path||busy" @click="choosePath(browseState.path)">选择当前目录<Check :size="16"/></button></div></template>

      <form v-if="modal==='plan'" @submit.prevent="saveForm"><label class="field">计划名称<input v-model="form.name" required maxlength="100" placeholder="例如：每日文档备份"/></label><div class="form-grid"><div><label class="field">备份来源</label><div class="checkbox-list"><label v-for="source in catalog.sources" :key="source.id" class="check-label"><input v-model="form.source_ids" type="checkbox" :value="source.id"/><span>{{source.name}}<small>{{source.path}}</small></span></label><p v-if="!data.sources.length" class="text-secondary">请先登记备份源。</p></div></div><label class="field">目标存储池<select v-model="form.pool_id" required><option value="" disabled>选择存储池</option><option v-for="pool in catalog.pools" :key="pool.id" :value="pool.id">{{pool.name}}</option></select></label></div><div class="form-section"><h3>时间安排</h3><div class="form-grid"><label class="field">Cron 表达式<input v-model="form.schedule" required placeholder="0 2 * * *"/><div class="schedule-presets"><button type="button" @click="form.schedule='0 2 * * *'">每天 02:00</button><button type="button" @click="form.schedule='0 2 * * 0'">每周日</button><button type="button" @click="form.schedule='@every 6h'">每 6 小时</button></div><small>五个字段：分、时、日、月、周。默认每日 02:00。</small></label><label class="field">执行时区<input v-model="form.timezone" required placeholder="Asia/Shanghai"/><small>使用 IANA 时区名，保存后显示接下来三次执行。</small></label></div></div><div class="form-section"><h3>历史保留</h3><div class="form-grid three"><label class="field">每日保留<input v-model.number="form.daily" type="number" min="0" required/></label><label class="field">每周保留<input v-model.number="form.weekly" type="number" min="0" required/></label><label class="field">每月保留<input v-model.number="form.monthly" type="number" min="0" required/></label></div></div><label class="field">计划排除规则（每行一条）<textarea v-model="form.excludes_text" rows="3" placeholder="**/*.tmp"/></label><div class="form-grid"><label class="field">失败重试次数<input v-model.number="form.retry_count" type="number" min="0" max="8" required/></label><label class="field">上传带宽上限 (KiB/s)<input v-model.number="form.bandwidth_kib" type="number" min="0" required/><small>0 表示不限制。</small></label></div><label class="check-label"><input v-model="form.enabled" type="checkbox"/>保存后启用定时计划</label><div class="modal-actions"><button type="button" class="button secondary" @click="closeModal">取消</button><button class="button primary" :disabled="busy||!form.source_ids?.length||!form.pool_id">保存计划</button></div></form>

      <template v-if="modal==='task'&&activeTask"><div class="task-detail-top"><div><span class="badge" :class="tone(activeTask.status)">{{statusLabel(activeTask.status)}}</span><h3>{{taskKind(activeTask.kind)}} · {{activeTask.name||planName(activeTask.plan_id)||activeTask.id.slice(0,12)}}</h3><code>{{activeTask.id}}</code></div><button class="button small secondary" @click="action(async()=>{await readTask();await loadLogs(logs.offset)})"><RefreshCw :size="15"/>刷新</button></div><div class="detail-stats"><div><span>扫描处理量</span><strong>{{bytes(activeTask.scanned_bytes)}}</strong></div><div><span>实际上传量</span><strong>{{bytes(activeTask.uploaded_bytes)}}</strong></div><div><span>云端净增长量</span><strong>{{bytes(activeTask.cloud_growth_bytes)}}</strong></div></div><dl class="task-facts"><div><dt>当前阶段</dt><dd>{{statusLabel(activeTask.stage)}}</dd></div><div><dt>开始时间</dt><dd>{{date(activeTask.started_at)}}</dd></div><div><dt>结束时间</dt><dd>{{date(activeTask.finished_at)}}</dd></div></dl><div v-if="activeTask.error" class="alert danger"><Shield :size="17"/><div>{{activeTask.error}}<small>{{activeTask.code}}</small></div></div><div v-if="detail" class="result-section"><h3>执行结果 / 分配报告</h3><ResultReport :result="detail" :accounts="catalog.accounts"/></div><div class="logs-head"><h3><Terminal :size="16"/>执行日志</h3><span class="text-secondary">共 {{logs.total}} 条</span></div><div class="log-view"><p v-if="!logs.items.length">暂无已记录的日志。任务状态来自服务端。</p><div v-for="(line,index) in logs.items" :key="line.seq??index"><span>{{line.seq??logs.offset+index+1}}</span><time v-if="line.at">{{date(line.at)}}</time><code>{{typeof line==='string'?line:line.line}}</code></div></div><div class="pagination"><span>第 {{Math.floor(logs.offset/100)+1}} 页</span><div><button class="icon-button" :disabled="logs.offset===0" @click="loadLogs(logs.offset-100)"><ChevronLeft :size="17"/></button><button class="icon-button" :disabled="logs.offset+100>=logs.total" @click="loadLogs(logs.offset+100)"><ChevronRight :size="17"/></button></div></div><div class="modal-actions"><button v-if="isActive(activeTask.status)" class="button danger" :disabled="busy" @click="cancelTask(activeTask)"><Square :size="14"/>取消任务</button><button class="button secondary" @click="closeModal">关闭</button></div></template>

      <form v-if="modal==='unlock'||modal==='export'" @submit.prevent="modal==='unlock'?unlock():exportKit()"><p class="section-description">{{modal==='unlock'?'输入备份库保护密码，解锁受保护的控制信息。':'为本次导出设置独立的恢复包保护密码。保存恢复包文件与密码，在异机恢复时使用。'}}</p><label class="field">{{modal==='unlock'?'备份库保护密码':'恢复包保护密码'}}<input v-model="form.password" type="password" :minlength="modal==='export'?12:1" required :autocomplete="modal==='export'?'new-password':'current-password'" placeholder="请输入保护密码"/></label><div v-if="modal==='export'" class="small-note"><KeyRound :size="16"/><span>恢复包包含受保护的解锁资料与发现入口，请在服务器以外保存一份。本次导出密码只保护此文件，不改变当前节点的备份库解锁密码。</span></div><div class="modal-actions"><button type="button" class="button secondary" @click="closeModal">取消</button><button class="button primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{modal==='unlock'?'解锁':'导出加密恢复包'}}</button></div></form>

      <template v-if="modal==='restore-preview'&&restorePreview"><div class="alert" :class="restorePreview.blocked?'danger':'success'"><ShieldCheck :size="20"/><div><strong>{{restorePreview.blocked?'预检查发现阻塞项':'恢复预检查完成'}}</strong><p>{{restorePreview.blocked?'处理缺失账号、权限或空间问题后再执行。':'请确认目标与恢复范围，结果以恢复任务报告为准。'}}</p></div></div><div class="detail-stats"><div><span>恢复条目</span><strong>{{restorePreview.file_count??'—'}}</strong></div><div><span>逻辑大小</span><strong>{{bytes(restorePreview.logical_bytes)}}</strong></div><div><span>所需空间</span><strong>{{bytes(restorePreview.required_bytes)}}</strong></div></div><div class="preview-summary"><p><strong>目标目录</strong><code>{{restoreForm.target}}</code></p><p><strong>冲突策略</strong>{{restoreForm.overwrite?'明确允许覆盖':'保留已有文件，不覆盖'}}</p><p><strong>缺失范围</strong>{{restoreForm.allow_partial?'接受明确的部分恢复':'要求完整范围可用'}}</p></div><div v-if="restorePreview.conflicts?.length" class="preview-list"><h3>目标冲突 · {{restorePreview.conflict_count??restorePreview.conflicts.length}} 项</h3><p v-if="restorePreview.conflict_count>restorePreview.conflicts.length" class="text-secondary">下面显示部分冲突条目；全部数量以服务端预检查统计为准。</p><p v-for="(f,index) in restorePreview.conflicts" :key="index"><File :size="14"/><code>{{f.source_id}}/{{f.path}}</code></p></div><div v-if="restorePreview.missing_accounts?.length||restorePreview.missing_file_count" class="preview-list"><h3>不可用账号与缺失范围 · {{restorePreview.missing_file_count??restorePreview.missing_files?.length??0}} 条目</h3><p v-for="id in restorePreview.missing_accounts" :key="id"><Cloud :size="14"/>{{accountName(id)}}</p><p v-for="(file,index) in restorePreview.missing_files" :key="index"><File :size="14"/><span class="filename">{{sourceName(file.source_id)}}/{{file.path}}</span></p></div><p v-if="restorePreview.code" class="text-secondary">{{restorePreview.code}}</p><div class="modal-actions"><button class="button secondary" @click="closeModal">返回调整</button><button class="button primary" :disabled="busy||restorePreview.blocked" @click="executeRestore"><ArrowDownToLine :size="16"/>开始恢复</button></div></template>

      <template v-if="modal==='retention-preview'&&retentionPreview"><p class="section-description">{{planName(maintenanceForm.plan_id)}} · 服务端已按全局恢复点与快照引用计算保留范围。请查看阻塞项与删除集合。</p><div class="alert" :class="retentionPreview.blocked?'danger':'success'"><ShieldCheck :size="18"/><div><strong>{{retentionPreview.blocked?'清理已暂停':'保留范围已计算'}}</strong><p v-for="reason in retentionPreview.reasons" :key="reason">{{reason}}</p></div></div><div class="detail-stats"><div><span>必须保留</span><strong>{{retentionPreview.keep_ids?.length??0}}</strong></div><div><span>可删除恢复点</span><strong>{{retentionPreview.delete_ids?.length??0}}</strong></div><div><span>候选清理快照</span><strong>{{retentionPreview.snapshots?.length??0}}</strong></div></div><div v-if="retentionPreview.delete_ids?.length" class="checkbox-list"><label v-for="id in retentionPreview.delete_ids" :key="id" class="check-label"><input v-model="retentionSelection" type="checkbox" :value="id"/><span>{{data.points.find(p=>p.id===id)?.name||'历史恢复点'}}<small>{{date(data.points.find(p=>p.id===id)?.finished_at)}} · {{id}}</small></span></label></div><p v-else class="text-secondary">当前保留策略下没有可以删除的恢复点。</p><div class="modal-actions"><button class="button secondary" @click="closeModal">取消</button><button class="button danger" :disabled="busy||retentionPreview.blocked||!retentionSelection.length" @click="applyRetention"><Trash2 :size="16"/>确认清理范围</button></div></template>
      <template v-if="modal==='confirm'"><div class="confirm-icon"><Shield :size="27"/></div><p class="confirm-description">{{confirmText}}</p><div class="modal-actions"><button class="button secondary" @click="closeModal">返回</button><button class="button danger" :disabled="busy" @click="confirmAction&&action(confirmAction)"><LoaderCircle v-if="busy" class="spin" :size="16"/>确认执行</button></div></template>
    </div></section></div>
    <Transition name="toast"><div v-if="notice" class="toast"><Check :size="18"/><span>{{notice}}</span><button class="icon-button" @click="notice=''"><X :size="15"/></button></div></Transition>
  </div>
</template>
